package com.estoqueinteligente.report;
import java.time.*;import java.time.temporal.ChronoUnit;import com.estoqueinteligente.product.*;
public class ExpiringReportResponse{private final Long id;private final String name,categoryName;private final Integer quantity;private final LocalDate expirationDate;private final long daysToExpire;private final ProductStatus status;public ExpiringReportResponse(ProductResponse p,LocalDate today){id=p.getId();name=p.getName();categoryName=p.getCategoryName();quantity=p.getQuantity();expirationDate=p.getExpirationDate();daysToExpire=ChronoUnit.DAYS.between(today,expirationDate);status=p.getStatus();}public Long getId(){return id;}public String getName(){return name;}public String getCategoryName(){return categoryName;}public Integer getQuantity(){return quantity;}public LocalDate getExpirationDate(){return expirationDate;}public long getDaysToExpire(){return daysToExpire;}public ProductStatus getStatus(){return status;}}
